  function formatBDT(value) {
    if (value === null) return "Price on request";
    return `\u09F3 ${new Intl.NumberFormat("en-BD", { maximumFractionDigits: 0 }).format(Number(value) || 0)}`;
  }
  function filterProducts(products, category = "All lamps") {
    if (!category || category === "All lamps") return products;
    return products.filter((product) => product.category === category);
  }
  function searchProducts(products, query = "") {
    const term = query.trim().toLowerCase();
    if (!term) return products;
    return products.filter((product) => {
      const searchable = [product.name, product.category, product.description, product.tone, ...product.specs || []].join(" ").toLowerCase();
      return searchable.includes(term);
    });
  }
  function addToCart(cart, productId, quantity = 1) {
    const amount = Math.max(1, Math.min(99, Math.floor(Number(quantity) || 1)));
    const existing = cart.find((item) => item.id === productId);
    if (existing) {
      return cart.map((item) => item.id === productId ? { ...item, quantity: item.quantity + amount } : item);
    }
    return [...cart, { id: productId, quantity: amount }];
  }
  function updateCartQuantity(cart, productId, quantity) {
    const nextQuantity = Math.max(0, Number(quantity) || 0);
    if (nextQuantity === 0) return cart.filter((item) => item.id !== productId);
    return cart.map((item) => item.id === productId ? { ...item, quantity: nextQuantity } : item);
  }
  function cartItemCount(cart) {
    return cart.reduce((total, item) => total + item.quantity, 0);
  }
  function cartTotal(cart, products) {
    return cart.reduce((total, item) => {
      const product = products.find((candidate) => candidate.id === item.id);
      return total + (product ? product.price * item.quantity : 0);
    }, 0);
  }
